-- art-doll-captainsalazar (ru)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, material, technique)
SELECT id, 'ru', $tr$Авторская кукла: капитан Салазар$tr$, $tr$Маленькая авторская кукла — капитан Салазар. Вылеплен из полимерной глины, расписан акриловыми красками и одет вручную. Кукла целиком ручной работы, в единственном экземпляре$tr$, $tr$Капитан Салазар — авторская кукла ручной работы по мотивам «Пиратов Карибского моря»

Эта авторская кукла в единственном экземпляре изображает капитана Армандо Салазара, легендарного охотника на пиратов из фильма «Пираты Карибского моря: Мертвецы не рассказывают сказки», — с ней оживает кусочек проклятых карибских морей.

Когда-то грозный капитан испанского флота, Салазар посвятил жизнь охоте на пиратов. Оказавшись в ловушке Треугольника Дьявола, он вернулся капитаном-призраком во главе мёртвой команды «Немой Мэри», ведомый старой обидой на Джека Воробья.

Ростом около 20 см, этот миниатюрный капитан Салазар передаёт мрачную, драматичную атмосферу персонажа. Суровое выражение лица, потрёпанный облик, одежда морского офицера и несомненное призрачное присутствие делают его похожим на капитана, вернувшегося из моря спустя долгое время после того, как ему полагалось остаться мёртвым.

Есть что-то очень уместное в том, чтобы Салазар стал миниатюрой: после долгих лет в ловушке Треугольника Дьявола ему наконец есть где стоять — хотя я бы не стала рассчитывать, что он простоит там тихо слишком долго.$tr$, $tr$Акриловые краски, полимерная глина, ткань, шерсть$tr$, $tr$Лепка и роспись вручную, ручная работа$tr$
  FROM figurines WHERE slug = 'art-doll-captainsalazar'
ON CONFLICT (figurine_id, lang) DO UPDATE
   SET name = COALESCE(NULLIF(figurine_translations.name, ''), EXCLUDED.name),
       short_text = COALESCE(NULLIF(figurine_translations.short_text, ''), EXCLUDED.short_text),
       full_description = COALESCE(NULLIF(figurine_translations.full_description, ''), EXCLUDED.full_description),
       material = COALESCE(NULLIF(figurine_translations.material, ''), EXCLUDED.material),
       technique = COALESCE(NULLIF(figurine_translations.technique, ''), EXCLUDED.technique);

-- granny-with-cats (ru)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, material)
SELECT id, 'ru', $tr$Бабушка с котами$tr$, $tr$Маленькая авторская кукла — бабушка с котами. Вылеплена из полимерной глины, расписана и одета вручную$tr$, $tr$Бабушка с котами — авторская кукла ручной работы в единственном экземпляре
(высота около 9–10 см)

Эта миниатюрная бабушка — авторская кукла в единственном экземпляре, целиком вылепленная вручную из полимерной глины и тщательно расписанная качественными акриловыми красками. С ней два её любимых полосатых кота, и вся сцена полна нежности, дружбы и обаяния обычных дней.

Каждая деталь сделана вручную — от выразительного лица и мягкой улыбки до одежды и крошечных пушистых друзей. Один кот удобно устроился у неё на плече, другой сидит у ног, и получается сценка, которая рассказывает свою историю.

Внутри проволочный каркас, руки и ноги двигаются; одежда сшита вручную специально для этого персонажа. Формы не используются, поэтому это настоящая кукла в единственном экземпляре, которую нельзя повторить в точности.

Эта миниатюрная авторская кукла — для собирателей рукотворных кукол, любителей кошек и народного искусства и для всех, кому дороги причудливые персонажи. Ей найдётся место на полке, в шкафчике с редкостями или в собрании миниатюр.

Высота куклы около 9–10 см, в комплекте два миниатюрных кота, которые видны на фотографиях. Её бережно упакуют в защитную упаковку и отправят с трек-номером. Обращайтесь с ней осторожно: это хрупкая коллекционная работа, созданная для того, чтобы на неё смотрели, а не играли.

Каждая кукла вылеплена вручную по отдельности, и у каждой свой характер. Эта маленькая бабушка с верными пушистыми спутниками приносит в любую коллекцию тепло, уют и немного волшебства рассказанной истории.$tr$, $tr$Полимерная глина, акриловые краски, лак, проволока, шерсть, ткань$tr$
  FROM figurines WHERE slug = 'granny-with-cats'
ON CONFLICT (figurine_id, lang) DO UPDATE
   SET name = COALESCE(NULLIF(figurine_translations.name, ''), EXCLUDED.name),
       short_text = COALESCE(NULLIF(figurine_translations.short_text, ''), EXCLUDED.short_text),
       full_description = COALESCE(NULLIF(figurine_translations.full_description, ''), EXCLUDED.full_description),
       material = COALESCE(NULLIF(figurine_translations.material, ''), EXCLUDED.material);

