-- jared-leto-doll (ru)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, material, technique)
SELECT id, 'ru', $tr$Кукла: Джаред Лето$tr$, $tr$Маленькая кукла-портрет Джареда Лето. Вылеплена из полимерной глины, расписана акриловыми красками и одета вручную. Фигурка целиком ручной работы, в единственном экземпляре$tr$, $tr$Авторская кукла «Джаред Лето на Met Gala», миниатюрная скульптура ручной работы (9–10 см)

Эта миниатюрная авторская кукла в единственном экземпляре ростом около 9–10 см с удивительной точностью повторяет знаменитый выход Джареда Лето на Met Gala. Голова-портрет тонко проработана вручную: тёмные волнистые волосы до плеч, мягкие черты лица и аккуратная борода безошибочно передают сходство с актёром.

На нём эффектное ярко-красное атласное платье в пол с высоким воротом и струящимися драпированными рукавами. На плечи наброшена сложная сбруя из сверкающих серебристых нитей страз, которые изящно ниспадают по всей длине красной ткани. В левой руке он держит миниатюрную копию собственной головы — с теми же волосами и чертами лица, — повторяя тот сюрреалистический момент на подиуме. Эта бережно сделанная вручную работа — авангардная вещь, которая притягивает взгляд и собирателей искусства, и поклонников поп-культуры.$tr$, $tr$Акриловые краски, полимерная глина, ткань, шерсть$tr$, $tr$Лепка и роспись вручную, ручная работа$tr$
