-- miniature-book-fairy-tales (ru)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description)
SELECT id, 'ru', $tr$Миниатюрная книга: сказки$tr$, $tr$Маленькая авторская фигурка — книга сказок. Страницы сделаны из книжных листов. Гном двигается. Миниатюра вылеплена из полимерной глины и расписана акриловыми красками. Целиком ручной работы, в единственном экземпляре$tr$, $tr$Каждая большая история начинается со слов «Жили-были…», и эта крошечная скульптура ловит волшебный миг перед самым началом приключения.

Среди страниц старой, потрёпанной книги сказок прячется любопытный маленький гном и тихонько выглядывает из грубо сколоченного деревянного окошка.

Особенно хороша эта миниатюра своим мягким движением. Гном подвешен внутри книги и плавно покачивается взад и вперёд, и кажется, будто он живой. С каждым лёгким движением он словно высовывается из окошка, спеша поприветствовать всякого, кто откроет дверь в его сказочный дом.

Вся работа сделана вручную из полимерной глины и других материалов; каждая фактура, каждый мазок и каждая декоративная деталь проработаны руками. Состаренная обложка, крошечные металлические детали, потёртые уголки и надпись от руки создают ощущение древнего волшебного тома, сохранившего на своих страницах последнюю тайну.

Это больше чем скульптура — это маленькая история в трёх измерениях, которая приглашает вообразить приключения, спрятанные в каждой забытой книге. Работа в единственном экземпляре, она славит вечное волшебство сказок, любопытство и веру в то, что между страницами книги всё ещё можно найти необыкновенные миры.$tr$
  FROM figurines WHERE slug = 'miniature-book-fairy-tales'
ON CONFLICT (figurine_id, lang) DO UPDATE
