       full_description = COALESCE(NULLIF(figurine_translations.full_description, ''), EXCLUDED.full_description);

-- miniature-edgar-allan-poe-book-sculpture (ru)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, material, technique, dimensions)
SELECT id, 'ru', $tr$Миниатюрная скульптура-книга «Эдгар Аллан По»$tr$, $tr$Миниатюрная скульптура-книга ручной работы в единственном экземпляре по мотивам Эдгара Аллана По — с готической башней, крошечным призраком, страницами из печатной бумаги и маятником. Высота около 11 см.$tr$, $tr$Миниатюрная скульптура-книга в единственном экземпляре по мотивам Эдгара Аллана По.
Высота около 11 см вместе с башней.

Эта маленькая готическая скульптура-книга сделана вручную из полимерной глины и тщательно расписана акриловыми красками. Обложка оформлена как потрескавшееся тёмное дерево с каменной кладкой, металлическими заклёпками и надписью «Edgar Allan Poe», сделанной от руки. В дверном проёме стоит крошечный призрак, блок книги сложен из страниц печатной бумаги, а изнутри книги выступает маленький маятник.

Подробности

- Миниатюрная литературная скульптура ручной работы
- По мотивам Эдгара Аллана По и готической прозы
- Вылеплена из полимерной глины и расписана акриловыми красками вручную
- Страницы из печатной бумаги
- Маленькая башня и каменная кладка наверху
- Крошечная фигура призрака в дверном проёме
- Маятник внутри книги
- Внутренний проволочный каркас для прочности
- Коллекционная работа в единственном экземпляре, копий не делается
- Высота: около 11 см

Кому подойдёт

- Любителям книг и собирателям готической литературы
- Экспозициям в духе По, готики или «тёмной академии»
- Книжной полке, письменному столу или уголку для чтения
- Собраниям миниатюры и ручного искусства
- Как необычный подарок ручной работы для поклонников классической литературы ужасов

Отправка и уход

- Бережно упаковывается в защитную упаковку
- Отправляется с трек-номером
- Обращайтесь осторожно: это хрупкий предмет ручной работы, а не игрушка.

Каждая работа вылеплена и расписана вручную по отдельности, поэтому у миниатюрной книги своя состаренная фактура, своё призрачное настроение и свой литературный характер.$tr$, $tr$Полимерная глина, акриловые краски, лак, проволока, бумага$tr$, $tr$Лепка и роспись вручную, ручная работа$tr$, $tr$Высота около 11 см$tr$
