-- small-art-doll-black-woman-with-basket (ru)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, material, technique)
SELECT id, 'ru', $tr$Маленькая авторская кукла: темнокожая женщина с корзиной$tr$, $tr$Маленькая авторская кукла — темнокожая деревенская женщина с корзиной овощей. Вылеплена из полимерной глины, расписана акриловыми красками и одета вручную. Фигурка целиком ручной работы, в единственном экземпляре$tr$, $tr$Она несёт корзину, полную только что собранных фруктов и овощей, будто возвращается домой с шумного деревенского рынка. Мягкая улыбка и спокойное лицо говорят о теплоте, доброте и тихом достоинстве обычной жизни. На ней простое льняное платье, яркие бусы, браслеты и пёстрый узорчатый тюрбан — в образе живёт красота народного ремесла и культурного наследия.

Кукла целиком сделана вручную из полимерной глины на проволочном каркасе: каждая деталь вылеплена, расписана и собрана руками. Выразительное лицо, тщательно проработанная фактура одежды, крошечные босые ступни и корзина, полная миниатюрных овощей, создают сцену, в которую веришь. Глубокие природные оттенки и тонкие украшения оживляют героиню: кажется, она только что пришла с оживлённой деревенской площади.

Высота около 11 см. Эта миниатюра в единственном экземпляре — оригинальная коллекционная работа для тех, кто ценит ручное искусство, выразительных персонажей и фольклор разных народов.$tr$, $tr$Акриловые краски, полимерная глина, ткань, шерсть$tr$, $tr$Лепка и роспись вручную, ручная работа$tr$
