-- small-doll-baba-yaga-2 (ru)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description)
SELECT id, 'ru', $tr$Маленькая кукла: Баба-Яга$tr$, $tr$Маленькая авторская кукла — Баба-Яга с метлой. Вылеплена из полимерной глины, расписана акриловыми красками и одета вручную. Фигурка целиком ручной работы, в единственном экземпляре.$tr$, $tr$Авторская кукла Баба-Яга с самодельной метлой (высота около 14–15 см)

Эта миниатюрная Баба-Яга в единственном экземпляре открывает дверь в зачарованный мир славянского фольклора. Мудрая, таинственная, незабываемая, она предстаёт легендарной лесной ведьмой, что живёт в глубине древнего леса. Сжимая простую самодельную метлу, она, кажется, вот-вот скроется на потайных лесных тропах или отправится в новое волшебное странствие по глуши.

Кукла целиком вылеплена вручную из полимерной глины и тщательно расписана качественными акриловыми красками, каждая деталь сделана руками. Глубоко выразительное лицо, пронзительный взгляд, обветренная кожа и непокорные волосы оживляют этот знаменитый фольклорный образ. На ней многослойная одежда ручной работы: потрёпанная шаль, простой фартук и деревенское платье, повторяющие вечный облик легендарной ведьмы.

Каждая кукла вылеплена, расписана и собрана вручную по отдельности, поэтому двух одинаковых не бывает. С обветренным лицом, всезнающим взглядом и традиционной метлой эта миниатюрная Баба-Яга передаёт тайну, мудрость и неувядающий дух одного из самых завораживающих образов восточноевропейского фольклора. Грозная колдунья, хранительница леса или хранительница древних тайн — какой бы её ни представляли, она остаётся единственной в своём роде коллекционной работой, которая приносит в собрание волшебство старых легенд.$tr$
