-- jared-leto-doll (uk)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, material, technique)
SELECT id, 'uk', $tr$Лялька Джаред Лето$tr$, $tr$Маленька лялька-портрет Джареда Лето. Виліплено з полімерної глини, розписано акриловими фарбами, одяг пошито вручну. Повністю ручна робота, фігурка в єдиному екземплярі$tr$, $tr$Авторська лялька в єдиному екземплярі: Джаред Лето на Met Gala, мініатюрна скульптура ручної роботи (9–10 см)

Ця впізнавана мініатюрна авторська лялька в єдиному екземплярі має близько 9–10 см заввишки й з неймовірною увагою до деталей відтворює славетний вихід Джареда Лето на Met Gala. Голова-портрет тонко опрацьована вручну: темне хвилясте волосся до плечей, лагідні риси обличчя й охайна борода точно передають безпомилкову схожість з актором.

На ньому ефектна яскраво-червона атласна сукня до підлоги з високим коміром і широкими драпірованими рукавами. На плечі накинуто вигадливу збрую з мерехтливих срібних низок страз, що граціозно спадають уздовж червоної тканини. У лівій руці він тримає мініатюрну копію власної виліпленої голови з таким самим волоссям і рисами обличчя, відтворюючи сюрреалістичну мить на подіумі. Цей неповторний твір, зроблений вручну й дбайливо, — авангардна окраса для колекціонерів мистецтва й шанувальників поп-культури.$tr$, $tr$Акрилова фарба, полімерна глина, тканина, вовна$tr$, $tr$Виліплено вручну, розписано вручну, ручна робота$tr$
