-- miniature-book-fairy-tales (uk)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description)
SELECT id, 'uk', $tr$Мініатюрна книга: казки$tr$, $tr$Маленька авторська фігурка: книга казок. Сторінки зроблено з книжкових аркушів. Гном рухається. Мініатюру виготовлено з полімерної глини й розписано акриловими фарбами. Повністю ручна робота, твір в єдиному екземплярі$tr$, $tr$Кожна велика історія починається словами «Жили-були…», і ця крихітна скульптура ловить чарівну мить перед самим початком пригоди.

Між сторінками старої, потертої книги казок захований допитливий маленький гном, що тихенько визирає з простого дерев’яного віконця.

Особливо чарівною цю мініатюру робить легкий рух. Гном підвішений усередині книги й м’яко гойдається туди-сюди, тож здається, що він живий. З кожним ледь помітним рухом він ніби висувається зі свого крихітного віконця, щоб привітати кожного, хто відчинить двері до його казкової оселі.

Увесь твір зроблено вручну з полімерної глини та інших матеріалів, і кожну фактуру, мазок пензля й оздоблення ретельно виконано вручну. Зістарена обкладинка, крихітні металеві деталі, потерті кути й рукописний напис створюють відчуття давнього чарівного фоліанта, що зберіг між сторінками останню таємницю.

Ця мініатюра — більше ніж скульптура: це маленька історія, втілена в трьох вимірах, яка запрошує уявити пригоди, сховані в кожній забутій книзі. Створена як колекційний твір в єдиному екземплярі, вона оспівує одвічні чари казок, допитливість і віру в те, що між сторінками книги ще можна знайти незвичайні світи.$tr$
  FROM figurines WHERE slug = 'miniature-book-fairy-tales'
