       full_description = COALESCE(NULLIF(figurine_translations.full_description, ''), EXCLUDED.full_description);

-- small-art-doll-forester (uk)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, material, technique)
SELECT id, 'uk', $tr$Маленька авторська лялька: лісовик$tr$, $tr$Маленька авторська лялька: лісовик із білками. Виліплено з полімерної глини, розписано акриловими фарбами, одяг пошито вручну. Повністю ручна робота, фігурка в єдиному екземплярі$tr$, $tr$Убраний у просту лляну туніку й теплу в’язану накидку, цей веселий маленький лісовий мандрівник почувається серед лісових звірів як удома. Дві крихітні білки обрали його своїм вірним товаришем: одна гордо сидить у нього на голові, а друга нетерпляче тягнеться з його долоні, і ця грайлива мить сповнена тепла й тихого гумору.

Ляльку повністю виліплено вручну з полімерної глини, і кожну деталь виготовлено окремо й ретельно розписано — від виразної усмішки й добрих очей до тонкої фактури бороди й одягу. Мініатюрні білки теж виліплені й розписані вручну, у кожної свій жвавий характер, тож уся композиція схожа на крихітну історію, що застигла в часі.

Лялька має гнучкий дротяний каркас, тож руки й ноги можна обережно переставляти, трохи змінюючи позу. Ця мініатюра заввишки близько 9 см в єдиному екземплярі створена для колекціонерів, які цінують виразних персонажів, ручну роботу й химерні фентезійні світи.

Серед лісових колекцій, казкових героїв чи в кабінеті дивовиж цей маленький лісовий друг приносить радість, доброту й дитяче відчуття дива. Кожну деталь виліплено, розписано, вдягнено й зібрано повністю вручну, тож точно повторити цього героя неможливо.$tr$, $tr$Акрилова фарба, полімерна глина, тканина, вовна$tr$, $tr$Виліплено вручну, розписано вручну, ручна робота$tr$
  FROM figurines WHERE slug = 'small-art-doll-forester'
ON CONFLICT (figurine_id, lang) DO UPDATE
   SET name = COALESCE(NULLIF(figurine_translations.name, ''), EXCLUDED.name),
       short_text = COALESCE(NULLIF(figurine_translations.short_text, ''), EXCLUDED.short_text),
       full_description = COALESCE(NULLIF(figurine_translations.full_description, ''), EXCLUDED.full_description),
       material = COALESCE(NULLIF(figurine_translations.material, ''), EXCLUDED.material),
       technique = COALESCE(NULLIF(figurine_translations.technique, ''), EXCLUDED.technique);

-- small-art-doll-frankenstein-s-creature (uk)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description)
SELECT id, 'uk', $tr$Маленька авторська лялька: створіння Франкенштейна$tr$, $tr$Маленька авторська лялька: створіння Франкенштейна. Виготовлено з полімерної глини, розписано акриловими фарбами, одяг пошито вручну. Повністю ручна робота, фігурка в єдиному екземплярі$tr$, $tr$
Народжене з уламків і оживлене неможливою іскрою, це мініатюрне прочитання створіння Франкенштейна передає і силу, і трагедію одного з найнезабутніших персонажів літератури. Це не бездумне чудовисько, а самотній мандрівник — пошрамований, обвітрений, що шукає собі місця у світі, який його боїться.

Ляльку заввишки близько 14–15 см ретельно виготовлено вручну з полімерної глини й убрано в багатошаровий, навмисно зношений одяг. Темний плащ із каптуром облямований грубим штучним хутром, а поношений чорний одяг і старі чоботи підкреслюють його важкий шлях. Ретельно намальовані шрами перетинають обличчя, шию й груди, надаючи фігурці напрочуд живого й драматичного виразу.

Окремо чи поруч з іншими класичними готичними героями, це крихітне створіння приносить у будь-яку колекцію сильну атмосферу таємниці й почуття.

Особливості:

Колекційна авторська лялька ручної роботи в єдиному екземплярі
Висота: близько 14–15 см
Виліплено з полімерної глини
Розписано вручну, з реалістичними рисами обличчя й шрамами
Убрано в зношений одяг ручної роботи з плащем із каптуром і облямівкою зі штучного хутра
За мотивами класичного роману Мері Шеллі
Для вітрини й колекції
Не іграшка, поводитися обережно

Маленька фігурка з величною історією — незабутня данина одному з найвідоміших персонажів готичної літератури.$tr$
