-- small-art-doll-gnome-with-gold (uk)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, material, technique)
SELECT id, 'uk', $tr$Маленька авторська лялька: гном із золотом$tr$, $tr$Маленька авторська лялька: гном із золотом. Виліплено з полімерної глини, розписано акриловими фарбами, одяг пошито вручну. Повністю ручна робота, фігурка в єдиному екземплярі$tr$, $tr$Цей химерний маленький гном виглядає так, ніби щойно вийшов зі старої лісової казки: трохи буркотливий, трохи загадковий і явно не в захваті від сучасного світу. Виразне обличчя, довга скуйовджена борода, кривий коричневий капелюх і яскраво-жовте вбрання ручної роботи надають йому чудово дивакуватого характеру.

Він несе крихітний простий кошик, повний золота, ніби щойно повернувся з лісу, де збирав щось важливе. Кожну деталь зроблено вручну, щоб створити відчуття мініатюрного казкового героя з власним характером і історією.

Мініатюрна авторська лялька в єдиному екземплярі для колекціонерів, які люблять фольклор, фентезі, героїв ручної роботи й крихітні світи, сповнені незвичайних персонажів.$tr$, $tr$Полімерна глина, акрилова фарба, лак, дріт, тканина, вовна$tr$, $tr$Виліплено вручну, розписано вручну, ручна робота$tr$
