-- small-art-doll-lady-agatha (uk)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, material)
SELECT id, 'uk', $tr$Маленька авторська лялька: леді Агата$tr$, $tr$Маленька авторська лялька: леді Агата. Виготовлено з полімерної глини, розписано акриловими фарбами, одяг пошито вручну. Повністю ручна робота, лялька в єдиному екземплярі$tr$, $tr$Ляльку повністю виліплено вручну з полімерної глини: кожну зморшку, лагідний вираз і тонку деталь окремо сформовано й розписано, щоб надати їй неповторного характеру. Сукню ручної роботи доповнюють мереживна шаль, крихітна сумочка під старовину, вигадливий кулон-сердечко й елегантний капелюх із пір’ям, що додає старосвітської чарівності. Завдяки гнучкому дротяному каркасу руки можна обережно переставляти, трохи змінюючи позу.

Маючи близько 10–11 см заввишки, вона — колекційний твір в єдиному екземплярі для тих, хто цінує мініатюрне мистецтво, виразних персонажів і ручну майстерність. У кабінеті дивовиж, серед казкових фігурок чи в особистій колекції вона приносить тепло, вишуканість і тиху загадковість.

Під час створення не використовуються ні форми, ні серійні прийоми. Кожен етап — від ліплення й розпису до шиття й складання — виконано повністю вручну, тож ця мініатюрна пані справді неповторний твір мистецтва, який ніколи не буде точно повторено.$tr$, $tr$Акрилова фарба, полімерна глина, тканина, вовна$tr$
