-- small-art-doll-little-ghost (uk)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, material, technique)
SELECT id, 'uk', $tr$Маленька авторська лялька: маленький привид$tr$, $tr$Маленька авторська лялька: маленький привид. Виліплено з полімерної глини, розписано акриловими фарбами. Повністю ручна робота, підвісна фігурка$tr$, $tr$Цей маленький підвісний привид — крихітний, трохи пустотливий герой із чудово моторошним характером. Завеликі сині очі, скуйовджене рудувате волосся, бліде виразне обличчя й довге біле вбрання роблять його схожим на допитливого маленького духа, що щойно з’явився звідкись між справжнім світом і старим будинком із привидами.

Його повністю виліплено вручну з полімерної глини й ретельно розписано, кожну крихітну деталь створено вручну окремо. Виразне обличчя, незвична зачіска, крихітні руки, поношені на вигляд черевики й старовинний ключ на грудях надають йому особливого характеру й трохи загадкової казкової атмосфери.

Маючи близько 10–11 см заввишки, він задуманий як підвісна мініатюрна декоративна авторська лялька. Руки закріплені й не рухаються, а ноги можна обережно згинати, трохи змінюючи позу, у якій він висить.

Це мініатюра ручної роботи в єдиному екземплярі, повністю зроблена вручну, тож другої точно такої ніколи не буде. Вона призначена для колекціонерів і вітрини, а не для гри, і через тендітні деталі ручної роботи поводитися з нею треба обережно.$tr$, $tr$Полімерна глина, акрилова фарба, лак, дріт, тканина, вовна$tr$, $tr$Виліплено вручну, розписано вручну, ручна робота$tr$
