-- small-art-doll-model (uk)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, material, technique)
SELECT id, 'uk', $tr$Маленька авторська лялька: модель$tr$, $tr$Маленька авторська лялька: модель (Дженел Моне). Виготовлено з полімерної глини, розписано акриловими фарбами, одяг пошито вручну. Повністю ручна робота, твір в єдиному екземплярі. Висота без капелюхів близько 15 см$tr$, $tr$Натхненна образом Дженел Моне, вона ступає так, ніби весь світ — її власний подіум, з легкою грацією тримаючи рівновагу під екстравагантною вежею з елегантних капелюхів. Кожна деталь мініатюри розповідає про жінку, яку впевненість, уява й безпомилкове відчуття стилю роблять незабутньою.

Цю авторську ляльку в єдиному екземплярі повністю виліплено й зібрано вручну: полімерна глина поєднується з ретельно скроєним текстилем, і виходить виразне поєднання модної скульптури й химерного образу.


Маючи близько 15 см заввишки, вона — неповторна колекційна річ для тих, хто цінує виразні мініатюри ручної роботи, мистецтво, натхненне модою, і оригінальні скульптурні історії.

Це більше ніж мініатюрна лялька: це крихітний твір мистецтва, у якому вишуканість поєднана з гумором, і щоразу, дивлячись на неї, можна вигадати власну історію.$tr$, $tr$Полімерна глина, акрилова фарба, лак, дріт, тканина, вовна$tr$, $tr$Виліплено вручну, розписано вручну, ручна робота$tr$
  FROM figurines WHERE slug = 'small-art-doll-model'
