-- small-art-doll-tailor (uk)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, material, technique)
SELECT id, 'uk', $tr$Маленька авторська лялька: кравець$tr$, $tr$Маленька авторська лялька: кравець. Виготовлено з полімерної глини, розписано акриловими фарбами, одяг пошито вручну. Повністю ручна робота$tr$, $tr$Ця авторська лялька «Кравець» в єдиному екземплярі — крихітний герой ручної роботи з полімерної глини з ретельно дібраними тканинами. Він постає традиційним кравцем серед дрібниць свого ремесла, і це надає мініатюрі теплого, ностальгійного й чудово химерного характеру.

Кожну деталь виліплено й оздоблено вручну, від виразного обличчя й одягу до крихітних тканинних елементів, що довершують образ. Поєднання полімерної глини й справжньої тканини робить цю маленьку фігурку особливо відчутною на дотик і правдивою.

Висота ляльки близько 10–12 см. Це твір ручної роботи в єдиному екземплярі, створений як колекційна мініатюра, а не іграшка. Він гарно доповнить колекцію мініатюрних персонажів, вітрину на тему шиття або стане неповторним подарунком для тих, хто любить ручну роботу, кравецтво й маленькі історії, втілені в скульптурі.$tr$, $tr$Акрилова фарба, полімерна глина, тканина$tr$, $tr$Виліплено вручну, розписано вручну, ручна робота$tr$
