       full_description = COALESCE(NULLIF(figurine_translations.full_description, ''), EXCLUDED.full_description);

-- small-art-doll-witch-2 (uk)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description)
SELECT id, 'uk', $tr$Маленька авторська лялька: відьма з посохом$tr$, $tr$Маленька авторська лялька: відьма з посохом. Виготовлено з полімерної глини, розписано акриловими фарбами, одяг пошито вручну$tr$, $tr$Лісова лялька в єдиному екземплярі з посохом-черепом (висота близько 14–15 см)

Ця мініатюрна лісова відьма в єдиному екземплярі веде у світ забутих легенд. Мудра, загадкова й позачасова, вона стоїть боса під обвітреним плащем і тримає давній дерев’яний посох, увінчаний крихітним черепом і пошарпаними стрічками, — мовчазні реліквії старих чарів і лісового фольклору. Хоча вигляд у неї моторошний, лагідний вираз обличчя натякає радше на хоронительку лісу, ніж на силу, якої варто боятися.

Ляльку повністю виліплено вручну з полімерної глини й ретельно розписано якісними акриловими фарбами, кожну деталь дбайливо зроблено вручну. Від виразного обличчя й розпущеного мідного волосся до багатошарового простого одягу й зістареного чарівного посоха — кожен елемент розповідає історію, натхненну європейськими казками й традиційним фольклором.

Кожну ляльку окремо ліплять, розписують і збирають вручну, тож двох однакових не буває. З давнім посохом, розпущеним мідним волоссям і загадковою усмішкою ця лісова відьма ніби зійшла зі сторінок старої казки, несучи мудрість забутих лісів і тихі чари природи. Вона — неповторна колекційна річ, створена, щоб будити уяву й стати дорогою окрасою будь-якої колекції фентезійного мистецтва ручної роботи.$tr$
