-- small-baba-yaga-with-bird (uk)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, material)
SELECT id, 'uk', $tr$Маленька Баба-Яга з пташкою$tr$, $tr$Маленька авторська лялька: Баба-Яга з мітлою. Виготовлено з полімерної глини, розписано й одягнено вручну. Висота близько 9 см$tr$, $tr$Ця мініатюрна Баба-Яга заввишки лише близько 9 см — авторська лялька ручної роботи в єдиному екземплярі, ретельно виліплена з полімерної глини й розписана вручну якісними акриловими фарбами. Натхненна загадковою хоронителькою зі слов’янського фольклору, вона постає не страшною відьмою, а давньою берегинею лісових таємниць.

Убрана в одяг ручної роботи й з крихітною мітлою в руках, Баба-Яга має супутницю — маленьку пташку, що стала її вірною лісовою подругою. Кожну зморшку, вираз і крихітну деталь окремо виліплено вручну, тож у ляльки свій особливий характер і позачасовий образ.

Фігурка має дротяний каркас, тож руки й ноги можна обережно згинати. Під час роботи форми не використовуються, тож кожна лялька — справжня колекційна річ в єдиному екземплярі, яку неможливо точно повторити.

Ця мініатюрна скульптура оспівує чари старих казок, зачарованих лісів і забутих легенд. Серед авторських ляльок, фентезійних колекційних речей чи на книжковій полиці вона запрошує уявити історії про лісові стежки, нашіптані закляття й несподівану дружбу.

Кожна лялька ручної роботи створюється окремо, терпляче й дбайливо, тож у кожного твору свій неповторний дух і чарівність.$tr$, $tr$Полімерна глина, акрилова фарба, лак, дріт, вовна, тканина$tr$
