INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, material, technique)
SELECT id, 'uk', $tr$Маленька лялька: гном із торбою$tr$, $tr$Маленька авторська лялька: гном зі своєю торбою. Виліплено з полімерної глини, розписано акриловими фарбами, одяг пошито вручну. Повністю ручна робота, фігурка в єдиному екземплярі.$tr$, $tr$Знайомтеся: чудово кошлатий маленький лісовий гном, допитливий мандрівник, що несе величезний наплічник у своїй мандрівці лісом. Крива гостроверха шапка, скуйовджене руде волосся, виразне обличчя, простий сільський одяг і завеликий наплічник роблять його схожим на того, хто роками ходить лісовими стежками й якось примудрився зібрати дорогою все, що може знадобитися.

Ця мініатюрна авторська лялька в єдиному екземплярі повністю виліплена й розписана вручну, а всередині дротяний каркас, тож руки й ноги можна трохи згинати, змінюючи позу. Одяг і аксесуари зроблено вручну з різних тканин і ретельно дібраних матеріалів, і це надає йому чудово простого, зістареного вигляду.

Заввишки він близько 10 см і гарно доповнить фентезійну чи лісову колекцію, вітрину з мініатюрами, діораму, сцену в ляльковому будиночку або просто особливе місце на полиці, звідки маленький лісовий мандрівник зможе пильнувати.

Це колекційна річ ручної роботи в єдиному екземплярі, тож другої точно такої ляльки ніколи не буде.$tr$, $tr$Полімерна глина, акрилова фарба, лак, дріт, тканина, вовна$tr$, $tr$Виліплено вручну, розписано вручну, ручна робота$tr$
  FROM figurines WHERE slug = 'small-doll-gnome-with-bag'
