INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, material, technique)
SELECT id, 'uk', $tr$Маленька лялька: гномиха$tr$, $tr$Маленька авторська лялька: гномиха з травами. Виліплено з полімерної глини, розписано акриловими фарбами, одяг пошито вручну. Повністю ручна робота, фігурка в єдиному екземплярі$tr$, $tr$Ця крихітна лісова героїня виглядає так, ніби все життя блукала лісом і збирала дорогою трави, сухі рослини й маленькі таємниці.

Гномиха має лише близько 10 см заввишки, але характер у неї чудовий і старосвітський. У руках вона тримає невеликий пучок трав, наче щойно повернулася з них десь із глибини лісу. Виразне обличчя, гострі вуха, довгі рудувато-каштанові коси й висока зелена шапка надають їй безпомилкового вигляду справжньої лісової гномихи, а тепле жовто-коричневе вбрання робить її схожою на героїню старої казки, зробленої вручну.
$tr$, $tr$Акрилова фарба, полімерна глина, тканина, вовна$tr$, $tr$Виліплено вручну, розписано вручну, ручна робота$tr$
