-- small-doll-granny-with-her-sheep (uk)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description)
SELECT id, 'uk', $tr$Маленька лялька: бабуся зі своєю вівцею$tr$, $tr$Маленька авторська лялька: бабуся зі своєю вівцею. Виліплено з полімерної глини, розписано акриловими фарбами, одяг пошито вручну. Повністю ручна робота, фігурка в єдиному екземплярі.$tr$, $tr$Ця чарівна маленька бабуся-пастушка ніби щойно вийшла з тихого села й дбайливо веде свою пухнасту вівцю старою лісовою стежкою. Трохи лукава усмішка й виразне обличчя надають їй теплого, грайливого характеру.

Вона вбрана в простий сільський одяг ручної роботи: фактурну коричневу спідницю, кремову блузку, яскраво-жовтий жилет і темну хустку. Образ довершує крихітний ціпок ручної роботи, а пухнаста овечка йде слідом.

Цю мініатюрну героїню в єдиному екземплярі повністю виліплено, розписано, вдягнено й зібрано вручну, з великою увагою до найменших дрібниць. Разом бабуся і її вівця розповідають просту маленьку історію про сільське життя, вірне товариство й мандри околицями.

Химерний твір для колекціонерів мініатюрного мистецтва ручної роботи, героїв у народному дусі й чарівних казкових сцен.$tr$
  FROM figurines WHERE slug = 'small-doll-granny-with-her-sheep'
ON CONFLICT (figurine_id, lang) DO UPDATE
   SET name = COALESCE(NULLIF(figurine_translations.name, ''), EXCLUDED.name),
       short_text = COALESCE(NULLIF(figurine_translations.short_text, ''), EXCLUDED.short_text),
       full_description = COALESCE(NULLIF(figurine_translations.full_description, ''), EXCLUDED.full_description);

-- small-doll-indian-man (uk)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description)
SELECT id, 'uk', $tr$Маленька лялька: індіанець$tr$, $tr$Маленька авторська лялька: корінний американець із соколом-сапсаном. Виготовлено з полімерної глини, розписано акриловими фарбами, одяг пошито вручну. Висота близько 12–13 см$tr$, $tr$Мініатюрний сокольник ручної роботи — хоронитель лісового яструба

Цей мініатюрний сокольник ручної роботи втілює одвічний зв’язок людини й хижих птахів. Спокійний, упевнений і глибоко вкорінений у природу, він стоїть із величним соколом на простягнутій руці, ніби вони вдвох пройшли незліченні мандри лісами, горами й відкритим небом.

Детальну мініатюру сокола ретельно виліплено й розписано вручну, і вона передає шляхетний вигляд цього дивовижного птаха.

Герой убраний у простий одяг за мотивами традиційного лісового вбрання. Фактурне темне пончо природно спадає з плечей, а м’які зелені штани й обмотки довершують практичне вбрання мандрівника, що почувається вдома серед природи. На шиї висять значущі прикраси ручної роботи, серед них кулон із кельтським вузлом і підвіска-перо бірюзового кольору, що додають ледь помітної символіки й таємниці.


У фентезійній колекції, у лісовому декорі чи серед мініатюрних фігурок ручної роботи цей сокольник приносить відчуття гармонії, пригоди й тихої сили. Неповторна колекційна річ для тих, хто любить природу, хижих птахів, фольклор і тонко опрацьоване мініатюрне мистецтво, — він розповідає одвічну історію довіри між хоронителем лісу та його вірним крилатим супутником.$tr$
  FROM figurines WHERE slug = 'small-doll-indian-man'
ON CONFLICT (figurine_id, lang) DO UPDATE
   SET name = COALESCE(NULLIF(figurine_translations.name, ''), EXCLUDED.name),
       short_text = COALESCE(NULLIF(figurine_translations.short_text, ''), EXCLUDED.short_text),
       full_description = COALESCE(NULLIF(figurine_translations.full_description, ''), EXCLUDED.full_description);

-- small-doll-lady-with-pigeons (uk)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, material, technique)
SELECT id, 'uk', $tr$Маленька лялька: пані з голубами$tr$, $tr$Маленька авторська лялька: пані з голубами. Виготовлено з полімерної глини, розписано акриловими фарбами, одяг пошито вручну. Повністю ручна робота, фігурка в єдиному екземплярі$tr$, $tr$

Волосся в неї скуйовджене, усмішка крива, а в очах та особлива іскра жінки, яка знає значно більше, ніж готова розповісти. Вона вбрана в линялий синій комбінезон і яскраво-червоні черевики й мандрує туди, куди ведуть її голуби, — а їх у неї чимало.

Одні сидять на капелюсі й на плечі, інші вірно йдуть біля ніг. Вона носить крихітну червону сумочку, у якій, мабуть, щось важливе… а може, просто крихти.

Є в ній щось чудово дивакувате. Вона не класична відьма й не зовсім лісова бабуся. Радше героїня, яка просто вийшла зі старої казки й вирішила залишитися.

Трохи загадкова, трохи пустотлива, дещо обвітрена й зовсім байдужа до того, що про неї думають.$tr$, $tr$Полімерна глина, акрилова фарба, лак, дріт, тканина, вовна$tr$, $tr$Виліплено вручну, розписано вручну, ручна робота$tr$
  FROM figurines WHERE slug = 'small-doll-lady-with-pigeons'
