       short_text = COALESCE(NULLIF(figurine_translations.short_text, ''), EXCLUDED.short_text),
       full_description = COALESCE(NULLIF(figurine_translations.full_description, ''), EXCLUDED.full_description),
       material = COALESCE(NULLIF(figurine_translations.material, ''), EXCLUDED.material),
       technique = COALESCE(NULLIF(figurine_translations.technique, ''), EXCLUDED.technique);

-- small-doll-little-vampire (uk)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description)
SELECT id, 'uk', $tr$Маленька лялька: маленький вампір$tr$, $tr$Маленька авторська лялька: вампір. Виліплено з полімерної глини, розписано акриловими фарбами, одяг пошито вручну. Повністю ручна робота, фігурка в єдиному екземплярі$tr$, $tr$Мініатюрний вампір із кулоном-хрестиком і книгою заклять — авторська лялька ручної роботи в єдиному екземплярі (висота близько 7–8 см)

Цю авторську ляльку в єдиному екземплярі повністю виліплено й розписано вручну, заввишки вона близько 7–8 см. У нього надзвичайно виразне, характерне обличчя з гострими вампірськими вухами, чіткими розписаними рисами й пильними очима.

Він убраний вручну в детально опрацьований готичний одяг під старовину: ефектний чорний плащ із високим коміром і насиченою червоною підкладкою, темний мереживний комір-жабо й мініатюрний кулон-хрестик сріблястого кольору на ланцюжку. Під пахвою він надійно тримає крихітну, ретельно зроблену книгу заклять. Усередині дротяний каркас, тож руки й ноги можна обережно згинати, трохи змінюючи позу. Кожну деталь оздоблено окремо, тому двох однакових ляльок не буває.

Ця колекційна мініатюра — для колекціонерів авторських ляльок, поціновувачів темного фентезі й тих, хто любить готичний, вампірський декор чи декор до Гелловіну. Він стане захопливою окрасою лялькового будиночка, тіньової скриньки, вітрини з дивовижами чи моторошної діорами.

Це тендітний твір ручної роботи: поводьтеся з ним обережно, бережіть від вологи, тепла й маленьких дітей. Кожне замовлення дбайливо загортається в захисну упаковку й надсилається з номером для відстеження.$tr$
  FROM figurines WHERE slug = 'small-doll-little-vampire'
ON CONFLICT (figurine_id, lang) DO UPDATE
   SET name = COALESCE(NULLIF(figurine_translations.name, ''), EXCLUDED.name),
       short_text = COALESCE(NULLIF(figurine_translations.short_text, ''), EXCLUDED.short_text),
       full_description = COALESCE(NULLIF(figurine_translations.full_description, ''), EXCLUDED.full_description);

-- small-doll-pirate-with-parrot (uk)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, material, technique)
SELECT id, 'uk', $tr$Маленька лялька: пірат із папугою$tr$, $tr$Маленька авторська лялька: пірат. Виготовлено з полімерної глини, розписано акриловими фарбами, одяг пошито вручну. Повністю ручна робота, фігурка в єдиному екземплярі.$tr$, $tr$Темна шкіряна куртка й картуз, поношений шарф, пасок, торба й крихітний птах на плечі надають йому безпомилкового вигляду мандрівного шибайголови зі старої книжки казок.

Виразне обличчя, неохайна борода, одяг ручної роботи й крихітна крива шабля дають йому чимало характеру, а маленький птах додає несподіваного відчуття товариства. Здається, він ось-ось зникне в середньовічному місті, на лісовій стежці чи в найближчій корчмі — бажано раніше, ніж хтось помітить шаблю.

Мініатюрна авторська лялька в єдиному екземплярі, ретельно зроблена вручну до найменших дрібниць, для колекціонерів, які люблять фольклор, фентезі, середньовічних героїв і мініатюрні історії.$tr$, $tr$Полімерна глина, акрилова фарба, лак, дріт, тканина, вовна$tr$, $tr$Виліплено вручну, розписано вручну, ручна робота$tr$
