-- small-doll-witch-2 (uk)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, material, technique)
SELECT id, 'uk', $tr$Маленька лялька: відьма$tr$, $tr$Маленька авторська лялька: відьма з мітлою. Виготовлено з полімерної глини, розписано акриловими фарбами, одяг пошито вручну. Повністю ручна робота, фігурка в єдиному екземплярі$tr$, $tr$Ця маленька відьма — авторська лялька ручної роботи в єдиному екземплярі, виліплена з полімерної глини й убрана в ретельно пошитий чорний одяг. У неї виразне обличчя, лукава усмішка, скуйовджене сиве волосся й висока, трохи крива гостроверха капелюха, що надає їй неповторного казкового характеру.

Вона тримає мітлу ручної роботи з натуральних волокон і грубої гілки, і це підкреслює її традиційний фольклорний образ. Чорна сукня оздоблена тонкими деталями, а на шиї висить маленький кулон.

Маючи близько 10 см заввишки, вона крихітна, але дуже детально опрацьована колекційна скульптура. Жвавий вираз і трохи дивакуватий вигляд роблять її схожою на героїню, що вийшла зі старої казки чи народної оповіді.

Ця відьма створена як колекційна авторська лялька: на неї дивляться, а не граються нею. Вона гарно доповнить колекцію фентезійних і фольклорних персонажів, мініатюрних скульптур чи авторських ляльок ручної роботи.$tr$, $tr$Полімерна глина, акрилова фарба, лак, дріт, тканина, вовна$tr$, $tr$Виліплено вручну, розписано вручну, ручна робота$tr$
