-- small-doll-witch-in-black (uk)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, material, technique)
SELECT id, 'uk', $tr$Маленька лялька: відьма в чорному$tr$, $tr$Маленька авторська лялька: відьма в чорному. Виготовлено з полімерної глини, розписано акриловими фарбами, одяг пошито вручну. Повністю ручна робота, фігурка в єдиному екземплярі$tr$, $tr$Авторська лялька: лісова відьма з мітлою й ключем, мініатюрна скульптура ручної роботи в єдиному екземплярі (9–10 см)

Ця мініатюрна авторська лялька-відьма в єдиному екземплярі має близько 9–10 см заввишки; її зловісний, але захопливий образ сповнений характеру темної казки. Обличчя ретельно виліплено вручну: лютий, загрозливий вираз, пильні очі під насупленими бровами, кривий гачкуватий ніс із виразною фактурою й глузливий рот, у якому видно гострі окремі зуби. Хмара скуйовдженого, неприборканого сивого волосся спадає на плечі з-під високого чорного гостроверхого капелюха, різко заломленого.

На ній темна чорна мантія з довгими рукавами й обтріпаними краями, що надають їй давнього, містичного вигляду. На шиї, мов головний медальйон, висить великий вигадливий латунний ключ під старовину. У руці вона міцно стискає високу дерев’яну гілку з мітлою з натуральної соломи внизу, а її тендітна поза тримається на тонких гострих чорних черевиках. Кожну деталь зроблено вручну, тож ця мініатюра — справді неповторна колекційна річ для поціновувачів фентезійного мистецтва й темного фольклору.$tr$, $tr$Акрилова фарба, полімерна глина, тканина, вовна$tr$, $tr$Виліплено вручну, розписано вручну, ручна робота$tr$
