-- small-doll-with-with-nest (uk)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, material, technique)
SELECT id, 'uk', $tr$Маленька лялька: відьма з гніздом$tr$, $tr$Маленька авторська лялька: відьма. Виліплено з полімерної глини, розписано акриловими фарбами, одяг пошито вручну. Повністю ручна робота, фігурка в єдиному екземплярі$tr$, $tr$Мініатюрна лісова відьма Баба-Яга з вороною в гнізді та мітлою — авторська лялька ручної роботи в єдиному екземплярі (висота близько 10 см)

Цю авторську ляльку в єдиному екземплярі повністю виліплено й розписано вручну, заввишки вона близько 10 см. У неї надзвичайно виразне, характерне обличчя з реалістичними зморшками, пильними очима й скуйовдженим фактурним сивим волоссям, у яке вплетено гілочки, а на маківці сидить крихітне пташине гніздо з мініатюрною чорною вороною.

Вона вбрана вручну в простий багатошаровий лісовий одяг: оливково-зелену лляну туніку, темний фартух, обірвану поношену хустку, а на шиї в неї кулон-ключ із черепом під старовину. У руках вона тримає дерев’яну мітлу ручної роботи — саме те, що треба для лісових пригод. Усередині дротяний каркас, тож руки й ноги можна обережно згинати, змінюючи позу. Кожну деталь виготовлено й оздоблено окремо, тому двох однакових ляльок не буває.

Ця колекційна мініатюра для колекціонерів авторських ляльок, поціновувачів слов’янського фольклору й Баби-Яги, а також для тих, хто любить темний сільський затишок і відьомський декор. Вона стане окрасою лялькового будиночка, тіньової скриньки, вітрини з дивовижами, лісової діорами чи казкової колекції. Це тендітний колекційний твір ручної роботи: поводьтеся з ним обережно, бережіть від вологи, тепла й маленьких дітей. Кожне замовлення дбайливо пакується в захисну упаковку й надсилається з номером для відстеження.$tr$, $tr$Акрилова фарба, полімерна глина, тканина, вовна$tr$, $tr$Виліплено вручну, розписано вручну, ручна робота$tr$
