INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, material, technique, dimensions)
SELECT id, 'uk', $tr$Крихітна авторська лялька в єдиному екземплярі: Баба-Яга$tr$, $tr$Мініатюрна авторська лялька Баба-Яга в єдиному екземплярі з виразним обличчям відьми, вовняним волоссям, текстильним одягом ручної роботи й дротяним каркасом, що дозволяє змінювати позу. Висота близько 9 см.$tr$, $tr$Мініатюрна авторська лялька Баба-Яга в єдиному екземплярі.
Висота близько 9 см.

Цю маленьку Бабу-Ягу ручної роботи виліплено з полімерної глини й ретельно розписано акриловими фарбами. У неї виразне зморшкувате обличчя, світле вовняне волосся, текстильний одяг ручної роботи з квітковими й мереживними деталями та маленькі обереги в народному дусі. Дротяний каркас дозволяє обережно згинати руки й ноги, тож її можна поставити стоячи або посадити.

Подробиці

- Авторська лялька, повністю виліплена й розписана вручну
- Виразне обличчя відьми Баби-Яги з тонким розписом
- Вовняне волосся й темна хустка
- Текстильний одяг ручної роботи з мереживною облямівкою
- Маленькі обереги у фольклорному дусі
- Дротяний каркас, руки й ноги згинаються
- Може стояти або сидіти
- Колекційний твір в єдиному екземплярі, копій не робиться
- Висота: близько 9 см

Для чого

- Колекції авторських ляльок і мініатюр
- Вітрини з Бабою-Ягою, відьмами, фольклором і казками
- Полиця до Гелловіну, осінній чи містичний декор
- Окраса мініатюрної сцени в дусі лялькового будиночка
- Діорами й сюжетна фотографія
- Особливий подарунок ручної роботи для колекціонера

Пересилання й догляд

- Дбайливо пакується в захисну упаковку
- З номером для відстеження
- Будь ласка, поводьтеся обережно. Це тендітний твір ручної роботи, а не іграшка.

Кожен твір окремо ліпиться й збирається вручну, тож у цієї Баби-Яги свій гострий вираз, своя постава й свій казковий характер.$tr$, $tr$Полімерна глина, акрилова фарба, лак, дріт, вовна, тканина$tr$, $tr$Виліплено вручну, розписано вручну, ручна робота$tr$, $tr$Висота близько 9 см$tr$
