INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, material, technique)
SELECT id, 'uk', $tr$Крихітний вампір$tr$, $tr$Маленька авторська лялька: вампір із ключем. Виліплено з полімерної глини, розписано акриловими фарбами, одяг пошито вручну. Повністю ручна робота, фігурка в єдиному екземплярі$tr$, $tr$У цього крихітного вампіра чудовий дивний старосвітський характер: він не стільки страшний класичний вампір, скільки загадкове маленьке створіння, що могло забрести сюди з вікторіанської готичної історії.

Маючи лише близько 7,5 см заввишки, він мініатюрний, але напрочуд детально опрацьований. Виразне, трохи втомлене обличчя, неслухняне сиво-каштанове волосся, чорний картуз і завеликий коричневий плащ надають йому вигляду майже обшарпаного аристократа. Тонке мереживо на шиї й рукавах додає витонченості, а маленький старовинний ключ на грудях змушує замислитися, що саме він тримає під замком.

Під пахвою він несе крихітну старовинну книгу, ніби щойно опівночі вийшов із якоїсь забутої бібліотеки. Його супроводжує мініатюрний павук, що додає сцені трохи моторошної чарівності.

Одяг, аксесуари, обличчя й крихітні деталі виготовлено й оздоблено вручну окремо. Усередині дротяний каркас, тож руки й ноги можна обережно згинати, змінюючи позу.

Це мініатюрна авторська лялька в єдиному екземплярі: другої точно такої ніколи не буде.

Крихітний дивакуватий вампір із книгою, ключем і павуком. Здається, він знає дуже цікаву таємницю, але, на жаль, нікому її не розповість.$tr$, $tr$Акрилова фарба, полімерна глина, тканина, вовна$tr$, $tr$Виліплено вручну, розписано вручну, ручна робота$tr$
  FROM figurines WHERE slug = 'tiny-vampire'
ON CONFLICT (figurine_id, lang) DO UPDATE
   SET name = COALESCE(NULLIF(figurine_translations.name, ''), EXCLUDED.name),
       short_text = COALESCE(NULLIF(figurine_translations.short_text, ''), EXCLUDED.short_text),
       full_description = COALESCE(NULLIF(figurine_translations.full_description, ''), EXCLUDED.full_description),
       material = COALESCE(NULLIF(figurine_translations.material, ''), EXCLUDED.material),
       technique = COALESCE(NULLIF(figurine_translations.technique, ''), EXCLUDED.technique);

-- witch-with-scull (uk)
INSERT INTO figurine_translations (figurine_id, lang, name, short_text, full_description, material, technique)
SELECT id, 'uk', $tr$Відьма з черепом$tr$, $tr$Маленька авторська лялька: відьма з черепом. Виліплено з полімерної глини, розписано акриловими фарбами, одяг пошито вручну. Повністю ручна робота, фігурка в єдиному екземплярі$tr$, $tr$Ця маленька відьма виглядає так, ніби кілька сотень років живе на узліссі дуже темного лісу й зібрала дорогою чимало таємниць.

Скуйовджене біле волосся, схоже на хмару, глибоко виразне обличчя й трохи лукава усмішка надають їй безпомилково старосвітського характеру. На ній яскраво-жовта блузка під простим коричневим жилетом, а довга спідниця складається з шарів поношеної фактурної тканини. Убрання всіяне крихітними деталями: старовинний ключ, кулон-сердечко, ланцюжки, маленькі підвіски, схожі на кістки, і великий череп, що висить біля подолу.

Одяг навмисно зістарений і трохи обірваний, тож вона схожа не так на класичну казкову відьму, як на дивну маленьку мандрівницю, що роками збирала цікаві речі в забутих місцях.

Ляльку повністю зроблено вручну: обличчя, руки, одяг, волосся й мініатюрні аксесуари виготовлено й оздоблено вручну окремо. Усередині дротяний каркас, тож руки й ноги можна обережно згинати, змінюючи позу.

Це авторська лялька в єдиному екземплярі, створена як маленька героїня, а не серійна фігурка. Другої точно такої ніколи не буде.
$tr$, $tr$Акрилова фарба, полімерна глина, тканина, вовна$tr$, $tr$Виліплено вручну, розписано вручну, ручна робота$tr$
  FROM figurines WHERE slug = 'witch-with-scull'
ON CONFLICT (figurine_id, lang) DO UPDATE
   SET name = COALESCE(NULLIF(figurine_translations.name, ''), EXCLUDED.name),
       short_text = COALESCE(NULLIF(figurine_translations.short_text, ''), EXCLUDED.short_text),
       full_description = COALESCE(NULLIF(figurine_translations.full_description, ''), EXCLUDED.full_description),
       material = COALESCE(NULLIF(figurine_translations.material, ''), EXCLUDED.material),
       technique = COALESCE(NULLIF(figurine_translations.technique, ''), EXCLUDED.technique);

