       ('eb77e5f9-e0c8-5202-baef-73352daae255'::uuid, $tr$Маленька авторська лялька: відьма з мітлою й книгою заклять, ручна робота в єдиному екземплярі, фото 11$tr$),
       ('eccb9c46-4790-54ea-8598-5cdd94023166'::uuid, $tr$Мініатюрна скульптура-книга за мотивами Едгара Аллана По, з готичною вежею й крихітним привидом, ручна робота з полімерної глини, фото 3$tr$),
       ('ef992d3f-cc08-507b-bde7-89eba10ce458'::uuid, $tr$Маленька авторська лялька: Баба-Яга з мітлою, сивим вовняним волоссям і в простому сільському одязі, ручна робота в єдиному екземплярі, фото 7$tr$),
       ('efb0014a-d88c-50a7-bf0d-d86a2882214f'::uuid, $tr$Маленька авторська лялька: чарівник із чорними птахами й довгою білою бородою, ручна робота в єдиному екземплярі, фото 11$tr$),
       ('f0ead13b-baea-58f1-9557-bc44f69384c7'::uuid, $tr$Авторська лялька: русалка в стилі стимпанк із чорним тканинним хвостом, позу можна змінювати, ручна робота в єдиному екземплярі, фото 7$tr$),
       ('f38a2bd4-d4e5-59d5-a561-dbf02f80aaee'::uuid, $tr$Маленька авторська лялька: стара русалка із сивим волоссям і тканинним хвостом, позу можна змінювати, ручна робота в єдиному екземплярі, фото 4$tr$),
       ('f5a5f102-3417-5229-8dd4-82a95b6e8e7f'::uuid, $tr$Маленька авторська лялька: руда відьма з мітлою в чорному капелюсі, ручна робота в єдиному екземплярі, фото 3$tr$),
       ('f8b4b628-cd58-57e8-a469-486b47313e0f'::uuid, $tr$Маленька авторська лялька: руда відьма з мітлою в чорному капелюсі, ручна робота в єдиному екземплярі, фото 8$tr$),
       ('fc2aa885-8c7d-5d10-af53-adbc8e472764'::uuid, $tr$Маленька авторська лялька: бабуся в дротяних окулярах зі своїм равликом, ручна робота в єдиному екземплярі, фото 2$tr$)) AS t(id, alt)
